import './pdfview';
const MAX_PAGES = 20;
const MAX_TEXT = 15000;

/*
 * Reads the text out of uploaded PDFs (using the bundled PDF.js) and turns it
 * into suggestions for a notice: a headline, a short summary, a category and
 * any dates mentioned. Everything runs locally; nothing leaves the server.
 *
 * Scanned PDFs (pictures of paper) contain no text, so they get no suggestions.
 */

/* ------------------------------------------------------------------ */
/* Text layout: items -> lines -> paragraphs                           */
/* ------------------------------------------------------------------ */

function linesFrom(items) {
  const parts = items
    .filter((it) => typeof it.str === 'string' && it.str.length)
    .map((it) => ({
      str: it.str,
      x: it.transform[4],
      y: it.transform[5],
      size: Math.hypot(it.transform[2], it.transform[3]) || Math.abs(it.transform[0]) || 10,
      width: it.width || 0,
    }));
  parts.sort((a, b) => b.y - a.y || a.x - b.x);

  const lines = [];
  for (const p of parts) {
    const line = lines.find((l) => Math.abs(l.y - p.y) < Math.max(l.size, p.size) * 0.45);
    if (line) {
      line.parts.push(p);
      line.size = Math.max(line.size, p.size);
    } else {
      lines.push({ y: p.y, size: p.size, parts: [p] });
    }
  }
  for (const l of lines) {
    l.parts.sort((a, b) => a.x - b.x);
    let text = '';
    let end = null;
    for (const p of l.parts) {
      if (end !== null && p.x - end > l.size * 0.15 && !/\s$/.test(text) && !/^\s/.test(p.str)) text += ' ';
      text += p.str;
      end = p.x + p.width;
    }
    l.text = text.replace(/\s+/g, ' ').trim();
  }
  return lines.filter((l) => l.text).sort((a, b) => b.y - a.y);
}

const isNoise = (t) => /^(page\s*)?\d+(\s*(of|\/)\s*\d+)?$/i.test(t);

function paragraphsFrom(lines) {
  const paras = [];
  let cur = null;
  let prev = null;
  for (const l of lines) {
    if (isNoise(l.text)) continue;
    const gap = prev ? prev.y - l.y : 0;
    const sizeChange = prev && Math.abs(l.size - prev.size) / Math.max(l.size, prev.size) > 0.15;
    if (!cur || gap > Math.max(prev.size, l.size) * 1.7 || sizeChange) {
      cur = { text: l.text, size: l.size, y: l.y };
      paras.push(cur);
    } else if (/[a-z]-$/.test(cur.text) && /^[a-z]/.test(l.text)) {
      cur.text = cur.text.slice(0, -1) + l.text; // re-join a hyphenated word
    } else {
      cur.text += ' ' + l.text;
    }
    prev = l;
  }
  return paras;
}

/* ------------------------------------------------------------------ */
/* Suggestions                                                         */
/* ------------------------------------------------------------------ */

function bodySize(paras) {
  // The font size that carries the most characters is the body text.
  const weight = new Map();
  for (const p of paras) {
    const k = Math.round(p.size);
    weight.set(k, (weight.get(k) || 0) + p.text.length);
  }
  let best = 10;
  let max = -1;
  for (const [k, w] of weight) if (w > max) { max = w; best = k; }
  return best;
}

function tidyTitle(t) {
  t = t.replace(/\s+/g, ' ').replace(/[\s:–—-]+$/, '').trim();
  // Posters often shout in capitals; make it read like a headline.
  if (t.length > 4 && t === t.toUpperCase() && /[A-Z]/.test(t)) {
    t = t.toLowerCase().replace(/(^|[\s(“"'-])(\p{L})/gu, (m, a, b) => a + b.toUpperCase());
  }
  return t.slice(0, 150);
}

function suggestHeadline(paras, pageHeight, body) {
  const big = paras.filter((p) => p.size >= body * 1.25 && p.text.length >= 3 && p.text.length <= 160);
  if (!big.length) return null;
  // Skip a letterhead in the top strip of the page when a real heading sits below it.
  const belowHeader = big.filter((p) => p.y < pageHeight * 0.86);
  const pool = belowHeader.length ? belowHeader : big;
  const maxSize = Math.max(...pool.map((p) => p.size));
  // Prefer the biggest text; between near-equals, the one nearest the top.
  return pool.filter((p) => p.size >= maxSize * 0.85).sort((a, b) => b.y - a.y)[0];
}

function suggestSummary(paras, headline, pageHeight) {
  const out = [];
  let length = 0;
  for (const p of paras) {
    if (headline && p.y >= headline.y) continue; // only what comes after the headline
    if (!headline && p.y > pageHeight * 0.86) continue; // skip letterhead
    if (headline && p.size > headline.size * 0.95) continue;
    if (p.text.length < 3) continue;
    out.push(p.text);
    length += p.text.length;
    if (length >= 320 || out.length >= 4) break;
  }
  let text = out.join('\n\n');
  if (text.length > 700) text = text.slice(0, 700).replace(/\s+\S*$/, '') + '…';
  return text;
}

const CATEGORY_WORDS = {
  'Health & Safety': ['fire', 'evacuat', 'first aid', 'first-aid', 'safety', 'hazard', 'alarm', 'accident', 'risk assessment', 'warden', 'injury', 'ppe'],
  Benefits: ['pension', 'benefit', 'health insurance', 'dental', 'salary sacrifice', 'enrolment', 'enrollment', 'bonus', 'cycle to work', 'wellbeing allowance'],
  Policy: ['policy', 'procedure', 'handbook', 'code of conduct', 'compliance', 'gdpr', 'regulation', 'guideline'],
  Training: ['training', 'course', 'workshop', 'e-learning', 'elearning', 'webinar', 'certification', 'mandatory learning', 'induction'],
  Events: ['social', 'party', 'celebration', 'quiz', 'bake', 'festive', 'raffle', 'drinks', 'fundraiser', 'charity', 'team lunch'],
  People: ['welcome', 'new starter', 'joiner', 'farewell', 'retire', 'promotion', 'congratulat', 'leaver', 'anniversary', 'new arrival'],
  'IT & Facilities': ['lift', 'elevator', 'parking', 'wifi', 'wi-fi', 'password', 'laptop', 'it support', 'maintenance', 'office move', 'printer', 'building works', 'heating', 'kitchen'],
};

function suggestCategory(title, text, categories) {
  const hay = ` ${text.toLowerCase()} `;
  const head = ` ${(title || '').toLowerCase()} `;
  let best = null;
  let bestScore = 0;
  for (const [cat, words] of Object.entries(CATEGORY_WORDS)) {
    if (!categories.includes(cat)) continue;
    let score = 0;
    for (const w of words) {
      const re = new RegExp(`\\b${w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'g');
      score += (hay.match(re) || []).length + 3 * (head.match(re) || []).length;
    }
    if (score > bestScore) { bestScore = score; best = cat; }
  }
  return bestScore >= 2 ? best : null;
}

const MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const MONTH_RE = '(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)';

// Find dates written with a month name ("18 December", "December 18th, 2026").
// Numeric dates like 04/05 are skipped: day/month order differs between countries.
function findDates(text, now = new Date()) {
  const found = new Map();
  const add = (d, m, y) => {
    const month = MONTHS.findIndex((x) => x.startsWith(m.toLowerCase().slice(0, 3)));
    const day = +d;
    if (month < 0 || day < 1 || day > 31) return;
    let year = y ? +y : now.getFullYear();
    let date = new Date(year, month, day);
    if (date.getMonth() !== month) return; // e.g. 31 February
    if (!y && date < new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7)) date = new Date(++year, month, day);
    const ahead = (date - now) / 86400000;
    if (ahead < -1 || ahead > 400) return; // only upcoming dates are useful for a take-down
    found.set(date.getTime(), date);
  };
  const dm = new RegExp(`\\b(\\d{1,2})(?:st|nd|rd|th)?(?:\\s+of)?\\s+${MONTH_RE}\\b\\.?(?:,?\\s+(\\d{4}))?`, 'gi');
  const md = new RegExp(`\\b${MONTH_RE}\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?\\b(?:,?\\s+(\\d{4}))?`, 'gi');
  let m;
  while ((m = dm.exec(text))) add(m[1], m[2], m[3]);
  while ((m = md.exec(text))) add(m[2], m[1], m[3]);
  return [...found.values()].sort((a, b) => a - b).slice(0, 4).map((d) => {
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  });
}

/**
 * Suggestions from the paragraphs of a page. Used for PDF text and for text
 * read from images by OCR (where "size" is the height of the text line).
 * paras: [{ text, size, y }] with y measured up from the bottom of the page.
 */
function suggestFromParagraphs(paras, pageHeight, categories, fullText, body) {
  const text = fullText || paras.map((p) => p.text).join('\n\n');
  const bodyPx = body || bodySize(paras);
  const headline = suggestHeadline(paras, pageHeight, bodyPx);
  const title = headline ? tidyTitle(headline.text) : null;
  return {
    title,
    summary: suggestSummary(paras, headline, pageHeight),
    category: suggestCategory(title, text, categories),
    dates: findDates(text),
  };
}

/* ------------------------------------------------------------------ */
/* Entry point                                                         */
/* ------------------------------------------------------------------ */

/**
 * Analyse a PDF buffer.
 * Returns { pages, text, hasText, textHeavy, suggestions: { title, summary, category, dates } }
 */
async function analysePdf(buffer, { categories = [] } = {}) {
  const lib = await PdfView.lib();
  const doc = await lib.getDocument({ data: new Uint8Array(buffer), ...PdfView.assetUrls(), verbosity: 0 }).promise;

  try {
    const pageCount = doc.numPages;
    const allParas = [];
    let first = null;
    for (let i = 1; i <= Math.min(pageCount, MAX_PAGES); i++) {
      const page = await doc.getPage(i);
      const { height } = page.getViewport({ scale: 1 });
      const paras = paragraphsFrom(linesFrom((await page.getTextContent()).items));
      if (i === 1) first = { paras, height };
      allParas.push(...paras);
      page.cleanup();
    }

    let text = allParas.map((p) => p.text).join('\n\n');
    if (text.length > MAX_TEXT) text = text.slice(0, MAX_TEXT).replace(/\s+\S*$/, '') + '…';
    const hasText = text.replace(/\s/g, '').length >= 20;
    const result = { pages: pageCount, text: hasText ? text : '', hasText, textHeavy: false, suggestions: null };
    if (!hasText) return result;

    const body = bodySize(first.paras.length ? first.paras : allParas);
    const firstChars = first.paras.reduce((n, p) => n + p.text.length, 0);
    // Letters and policies (lots of small text) read better as text on a TV than as a page image.
    result.textHeavy = firstChars > 500 && body <= 16;

    result.suggestions = suggestFromParagraphs(first.paras, first.height, categories, text, body);
    return result;
  } finally {
    await doc.loadingTask.destroy();
  }
}

export { analysePdf, suggestFromParagraphs, findDates };

